//! Project-level memory and per-workspace settings.
//!
//! Link Code reads project instructions from the workspace itself:
//!
//! * `LINK.md` — the primary project memory file (generated by `/init`).
//! * `.link/rules/*.md` — extra rule files, concatenated in name order.
//! * `.link/settings.json` — permission allow/deny rules for this workspace.
//! * `.link/commands/*.md` — user-defined slash commands.

use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::error::{LinkError, Result};
use crate::permission::PermissionRules;

/// Name of the project memory file at the workspace root.
pub const MEMORY_FILE: &str = "LINK.md";

/// `<workspace>/.link`
pub fn link_dir(root: &Path) -> PathBuf {
    root.join(".link")
}

/// `<workspace>/.link/settings.json`
pub fn settings_path(root: &Path) -> PathBuf {
    link_dir(root).join("settings.json")
}

/// `<workspace>/.link/rules`
pub fn rules_dir(root: &Path) -> PathBuf {
    link_dir(root).join("rules")
}

/// `<workspace>/.link/commands`
pub fn commands_dir(root: &Path) -> PathBuf {
    link_dir(root).join("commands")
}

/// Project instructions loaded from disk and injected into the system prompt.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ProjectMemory {
    /// Concatenated instruction text, with per-file headers.
    pub instructions: String,
    /// Every file that contributed, in load order.
    pub sources: Vec<PathBuf>,
}

impl ProjectMemory {
    /// Load `LINK.md` and `.link/rules/*.md` from a workspace root.
    /// Missing files are not an error; a workspace without memory is normal.
    pub fn load(root: &Path) -> Self {
        let mut sources = Vec::new();
        let mut sections = Vec::new();

        let memory_file = root.join(MEMORY_FILE);
        if let Ok(text) = std::fs::read_to_string(&memory_file) {
            if !text.trim().is_empty() {
                sections.push(format!("# Project instructions ({MEMORY_FILE})\n{text}"));
                sources.push(memory_file);
            }
        }

        let mut rule_files = Vec::new();
        if let Ok(entries) = std::fs::read_dir(rules_dir(root)) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|e| e.to_str()) == Some("md") {
                    rule_files.push(path);
                }
            }
        }
        rule_files.sort();
        for path in rule_files {
            if let Ok(text) = std::fs::read_to_string(&path) {
                if !text.trim().is_empty() {
                    let name = path
                        .file_name()
                        .map(|n| n.to_string_lossy().into_owned())
                        .unwrap_or_default();
                    sections.push(format!("# Project rule ({name})\n{text}"));
                    sources.push(path);
                }
            }
        }

        Self {
            instructions: sections.join("\n\n"),
            sources,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.instructions.trim().is_empty()
    }

    /// The section injected into the system prompt, or an empty string.
    pub fn system_section(&self) -> String {
        if self.is_empty() {
            String::new()
        } else {
            format!("\n\n## Project memory\n\n{}", self.instructions.trim())
        }
    }
}

/// Per-workspace settings persisted in `.link/settings.json`.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct WorkspaceSettings {
    pub version: u32,
    pub permissions: PermissionRules,
    /// Additional instruction files to load, relative to the workspace root.
    pub extra_rule_files: Vec<String>,
    /// Commands never allowed to run in this workspace, by name.
    pub disabled_tools: Vec<String>,
}

impl WorkspaceSettings {
    pub fn load(root: &Path) -> Self {
        let path = settings_path(root);
        match std::fs::read_to_string(&path) {
            Ok(text) if !text.trim().is_empty() => {
                serde_json::from_str(&text).unwrap_or_else(|error| {
                    tracing::warn!(?error, path = %path.display(), "ignoring malformed .link/settings.json");
                    Self::default()
                })
            }
            _ => Self::default(),
        }
    }

    pub fn save(&self, root: &Path) -> Result<()> {
        let dir = link_dir(root);
        std::fs::create_dir_all(&dir).map_err(|e| LinkError::io(&dir, e))?;
        crate::config::write_json_atomic(&settings_path(root), self)
    }
}

/// A user-defined slash command from `.link/commands/*.md`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CustomCommand {
    /// Command name, taken from the file name without extension.
    pub name: String,
    /// One-line description (front-matter `description:` or first non-empty line).
    pub description: String,
    /// The prompt template. `$ARGUMENTS` is replaced with whatever the user typed.
    pub template: String,
    pub path: PathBuf,
}

impl CustomCommand {
    /// Expand the template for a given argument string.
    pub fn render(&self, arguments: &str) -> String {
        if self.template.contains("$ARGUMENTS") {
            self.template.replace("$ARGUMENTS", arguments)
        } else if arguments.trim().is_empty() {
            self.template.clone()
        } else {
            format!("{}\n\n{arguments}", self.template)
        }
    }
}

/// Load every custom command for a workspace, sorted by name.
pub fn load_custom_commands(root: &Path) -> Vec<CustomCommand> {
    let mut commands = Vec::new();
    let Ok(entries) = std::fs::read_dir(commands_dir(root)) else {
        return commands;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("md") {
            continue;
        }
        let Some(name) = path.file_stem().map(|s| s.to_string_lossy().into_owned()) else {
            continue;
        };
        let Ok(text) = std::fs::read_to_string(&path) else {
            continue;
        };
        let (description, body) = split_front_matter(&text);
        let description = description.unwrap_or_else(|| {
            body.lines()
                .map(str::trim)
                .find(|line| !line.is_empty())
                .unwrap_or("")
                .to_string()
        });
        commands.push(CustomCommand {
            name,
            description,
            template: body.to_string(),
            path,
        });
    }
    commands.sort_by(|a, b| a.name.cmp(&b.name));
    commands
}

/// Split an optional leading `--- description: ... ---` block from the body.
fn split_front_matter(text: &str) -> (Option<String>, &str) {
    let trimmed = text.trim_start_matches('\u{feff}');
    if !trimmed.starts_with("---") {
        return (None, trimmed);
    }
    let rest = &trimmed[3..];
    let Some(end) = rest.find("\n---") else {
        return (None, trimmed);
    };
    let (front, body) = rest.split_at(end);
    let body = body.trim_start_matches("\n---").trim_start_matches('\n');
    let description = front.lines().find_map(|line| {
        let line = line.trim();
        line.strip_prefix("description:")
            .map(|value| value.trim().trim_matches('"').to_string())
    });
    (description, body)
}

/// Cheap stack detection used by `/init` and the welcome screen.
///
/// Deliberately dependency-free: it looks for marker files rather than running
/// a build system.
pub fn detect_project_kinds(root: &Path) -> Vec<String> {
    let markers: [(&str, &str); 14] = [
        ("Cargo.toml", "Rust (Cargo)"),
        ("package.json", "Node.js"),
        ("tsconfig.json", "TypeScript"),
        ("pyproject.toml", "Python (pyproject)"),
        ("requirements.txt", "Python (pip)"),
        ("go.mod", "Go"),
        ("pom.xml", "Java (Maven)"),
        ("build.gradle", "Java/Kotlin (Gradle)"),
        ("CMakeLists.txt", "C/C++ (CMake)"),
        ("Makefile", "Make"),
        ("Gemfile", "Ruby"),
        ("composer.json", "PHP"),
        ("mix.exs", "Elixir"),
        ("Dockerfile", "Docker"),
    ];
    let mut kinds = Vec::new();
    for (file, label) in markers {
        if root.join(file).exists() {
            kinds.push(label.to_string());
        }
    }
    kinds
}

/// The prompt `/init` sends to the model to produce a `LINK.md`.
pub fn init_prompt(project_name: &str, kinds: &[String]) -> String {
    let kinds = if kinds.is_empty() {
        "unknown stack".to_string()
    } else {
        kinds.join(", ")
    };
    format!(
        "Explore this repository ({project_name}; detected stack: {kinds}) and write a concise 
project memory file. Cover: purpose, layout, how to build, how to run the tests, coding 
conventions, and anything a new contributor must not break. Return only the Markdown body, 
no code fences, at most 80 lines."
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn workspace() -> tempfile::TempDir {
        tempfile::tempdir().unwrap()
    }

    #[test]
    fn loads_memory_file_and_sorted_rules() {
        let dir = workspace();
        std::fs::write(dir.path().join(MEMORY_FILE), "Use Rust 2021.").unwrap();
        std::fs::create_dir_all(rules_dir(dir.path())).unwrap();
        std::fs::write(rules_dir(dir.path()).join("b.md"), "Rule B").unwrap();
        std::fs::write(rules_dir(dir.path()).join("a.md"), "Rule A").unwrap();
        std::fs::write(rules_dir(dir.path()).join("ignore.txt"), "nope").unwrap();

        let memory = ProjectMemory::load(dir.path());
        assert_eq!(memory.sources.len(), 3);
        let instructions = &memory.instructions;
        assert!(instructions.contains("Use Rust 2021."));
        // rules are loaded in name order
        let a = instructions.find("Rule A").unwrap();
        let b = instructions.find("Rule B").unwrap();
        assert!(a < b, "rules should be sorted by file name");
        assert!(memory.system_section().contains("## Project memory"));
    }

    #[test]
    fn empty_workspace_has_no_memory_section() {
        let dir = workspace();
        let memory = ProjectMemory::load(dir.path());
        assert!(memory.is_empty());
        assert_eq!(memory.system_section(), "");
    }

    #[test]
    fn custom_commands_use_front_matter_description() {
        let dir = workspace();
        std::fs::create_dir_all(commands_dir(dir.path())).unwrap();
        std::fs::write(
            commands_dir(dir.path()).join("review.md"),
            "---\ndescription: Review staged changes\n---\nReview $ARGUMENTS carefully.",
        )
        .unwrap();
        std::fs::write(commands_dir(dir.path()).join("plain.md"), "Just do it").unwrap();

        let commands = load_custom_commands(dir.path());
        assert_eq!(commands.len(), 2);
        assert_eq!(commands[0].name, "plain");
        assert_eq!(commands[0].description, "Just do it");
        assert_eq!(commands[1].name, "review");
        assert_eq!(commands[1].description, "Review staged changes");
        assert_eq!(commands[1].render("src/main.rs"), "Review src/main.rs carefully.");
        assert_eq!(commands[0].render(""), "Just do it");
    }

    #[test]
    fn detects_known_project_kinds() {
        let dir = workspace();
        std::fs::write(dir.path().join("Cargo.toml"), "[package]").unwrap();
        std::fs::write(dir.path().join("package.json"), "{}").unwrap();
        let kinds = detect_project_kinds(dir.path());
        assert!(kinds.contains(&"Rust (Cargo)".to_string()));
        assert!(kinds.contains(&"Node.js".to_string()));
        assert!(detect_project_kinds(&dir.path().join("nowhere")).is_empty());
    }

    #[test]
    fn workspace_settings_round_trip() {
        let dir = workspace();
        let mut settings = WorkspaceSettings::default();
        settings.permissions.allow_always.insert("bash:cargo test*".into());
        settings.permissions.deny_always.insert("bash:rm*".into());
        settings.save(dir.path()).unwrap();

        let loaded = WorkspaceSettings::load(dir.path());
        assert!(loaded.permissions.allow_always.contains("bash:cargo test*"));
        assert!(loaded.permissions.deny_always.contains("bash:rm*"));
    }

    #[test]
    fn malformed_workspace_settings_fall_back_to_default() {
        let dir = workspace();
        std::fs::create_dir_all(link_dir(dir.path())).unwrap();
        std::fs::write(settings_path(dir.path()), "{oops").unwrap();
        let loaded = WorkspaceSettings::load(dir.path());
        assert!(loaded.permissions.allow_always.is_empty());
    }

    #[test]
    fn init_prompt_mentions_stack() {
        let prompt = init_prompt("my-app", &["Rust (Cargo)".to_string()]);
        assert!(prompt.contains("my-app"));
        assert!(prompt.contains("Rust (Cargo)"));
    }
}
